| order by LastSeen desc

kqlCommunity.query:
// Entra Passkey Addition Threat Detection
// https://www.linkedin.com/posts/activity-7184406157707390977-6N3C/

//Entra Passkey Addition Threat Detection KQL:

AuditLogs
| where ActivityDisplayName == "Add Passkey (device-bound) security key"
| where Result == "success"
| extend AccountUPN = TargetResources[0].userPrincipalName
| extend AAGUID = AdditionalDetails[1].value
| extend WebAuthnInfo = AdditionalDetails[0].value
| project TimeGenerated, AccountUPN, ActivityDisplayName, AAGUID, WebAuthnInfo

// MITRE ATT&CK Mapping

// Based on the operations and objectives of the KQL code, the following MITRE ATT&CK techniques are relevant:

// T1078 - Valid Accounts:
// Description: Adversaries may use valid accounts to maintain access to victim systems.
// Relevance: Adding a passkey could be part of an adversary’s attempt to maintain access using legitimate credentials.
// T1556.004 - Unsecured Credentials: Web Session Cookie:
// Description: Adversaries may steal or forge web session cookies to gain access to web applications.
// Relevance: The extraction of WebAuthn information could be related to securing or exploiting web session credentials.
// T1556 - Modify Authentication Process:
// Description: Adversaries may modify authentication mechanisms to bypass security controls.
// Relevance: Adding a new passkey could be an attempt to modify the authentication process.

// Detecting High Risk Passkey Users
// https://www.linkedin.com/posts/activity-7193644152645959682-ylGM/

// As the use of passkeys becomes more popular due to their phishing-resistant advantages and their additional security through device biometrics, it’s important to recognize that there is still a risk of device compromise or potential compromise of the password manager storing the sync-able passkey. Consequently, security operations must actively monitor passkey users who are considered high risk and be prepared to revoke their passkeys when necessary or exclude them from the FIDO sign in policy.

// KQL for detecting High Risk Passkey Users: 

SigninLogs
| where RiskEventTypes_V2 != "[]"
| where RiskLevelAggregated == "high"
| where RiskLevelDuringSignIn == "high"
| where RiskState == "atRisk"
| where AuthenticationDetails contains "FIDO2 security key"

// MITRE ATT&CK Mapping

// Based on the operations and objectives of the KQL code, the following MITRE ATT&CK techniques are relevant:

// T1078 - Valid Accounts:
// This technique involves the use of valid accounts to gain access to systems. High-risk sign-ins with FIDO2 security keys could indicate an attempt to use compromised credentials.
// T1556 - Modify Authentication Process:
// This technique involves modifying the authentication process to bypass security controls. High-risk sign-ins with specific authentication methods like FIDO2 security keys could be part of an // attempt to manipulate the authentication process.
// T1071 - Application Layer Protocol:
// This technique involves the use of application layer protocols for command and control. High-risk sign-ins could be part of an adversary’s attempt to establish a foothold using legitimate protocols.

// Detecting FIDO2 Passkey Abuse🔥

// Max Rozendaal from Secura has penned an insightful blog titled “Abusing FIDO2 Passkeys to Take Over Global Administrators in Entra ID.” In this post, he delves into a critical attack vector, demonstrating how Microsoft’s Graph API for provisioning FIDO2 passkeys could be exploited to gain control over accounts with high-level privileges. (Blog link will be shared in the comments.)
// To address this issue, I’ve developed a Sentinel Graph API KQL threat detection script inspired by Max’s findings. You can download the KQL code from my SlimKQL GitHub Repository, which is highlighted on my LinkedIn profile. Just search for “Detecting FIDO2 Passkey Abuse.”

let AbusedRoleMonitor = dynamic(["Privileged Role Administrator", "Global Administrator"]);
let FIDOAccountObjID =
MicrosoftGraphActivityLogs
| where RequestUri has "/authentication/fido2Methods/creationOptions"
| where RequestMethod == "GET" and ResponseStatusCode == 200
| parse RequestUri with "https://graph.microsoft.com/beta/users/" 
UserObjectID "/authentication/fido2Methods/creationOptions"
| distinct UserObjectID;
IdentityInfo
| where AccountObjectId has_any(FIDOAccountObjID)
| summarize arg_max(TimeGenerated, *) by AccountObjectId
| where AssignedRoles has_any(AbusedRoleMonitor)

//  T1111: Multi-Factor Authentication Interception

// Add Passkey device-bound MS Authenticator Windows Hello detection
// https://www.linkedin.com/posts/activity-7191839187543728128-DQ02/

// With the public preview of expanding Entra passkey options, Entra admins will now need to make sure passkeys are properly managed as part of the security key life cycle management for both privilege and non-privilege roles. Security operations will also need to have detection on *NEW* passkey added from both malicious or non-malicious perspectives so that threat can be monitor and mitigated when required.🫡 

AuditLogs
| where ActivityDisplayName contains "Add Passkey"
| where Result == "success"
| extend AccountUPN = TargetResources[0].userPrincipalName
| extend AAGUID = AdditionalDetails[1].value
| extend WebAuthnInfo = AdditionalDetails[0].value
| project TimeGenerated, AccountUPN, ActivityDisplayName, AAGUID, WebAuthnInfo

// MITRE ATT&CK Mapping

// Based on the activities and data being extracted, the following MITRE ATT&CK techniques are relevant:

// T1078 - Valid Accounts:
// The query is identifying successful additions of passkeys, which can be related to the use of valid accounts for authentication purposes.
// T1556 - Modify Authentication Process:
// Adding a passkey can be seen as modifying the authentication process, which falls under this technique.
// T1589 - Gather Victim Identity Information:
// Extracting user principal names and WebAuthn information can be related to gathering identity information.

//This query looks up AAGUIDs with their device manufacturer using Passkey Explorer
//Can be joined with audit logs to track passkey additions
let PasskeyExplorer = externaldata(Guid: dynamic )[@"https://raw.githubusercontent.com/passkeydeveloper/passkey-authenticator-aaguids/main/combined_aaguid.json"] with (format="txt", ignoreFirstRecord=false)
| mv-expand kind=array Guid
| extend AAGUID = tostring(Guid[0])
| extend KeyName = Guid[1].name
| project-away Guid;
//PasskeyExplorer
//Example usage, join to audit logs
AuditLogs
| where ActivityDisplayName contains "Add Passkey"
| where Result == "success"
| extend AccountUPN = TargetResources[0].userPrincipalName
| extend AAGUID = tostring(AdditionalDetails[1].value)
| extend WebAuthnInfo = AdditionalDetails[0].value
| join kind=leftouter PasskeyExplorer on AAGUID
| project TimeGenerated, AccountUPN, ActivityDisplayName, AAGUID, WebAuthnInfo, KeyName
